from metpy.io.text import _decode_coords

def test_decode_coords():
    # Northern Hemisphere
    assert _decode_coords('6251365') == (-136.5, 62.5)
    # Southern Hemisphere
    assert _decode_coords('-3880854') == (-85.4, -38.8)
    print("Tests passed!")

if __name__ == "__main__":
    try:
        test_decode_coords()
    except AssertionError as e:
        print(f"Assertion failed")
        exit(1)
    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)

